/** Owned A37 Salesforce fixture. Every run rolls back its own inserted records. */
public class A37Oracle {
    public static Boolean enabled = false;
    public static String targetEvent;
    public static String action;
    public static Integer recursionLimit;
    public static Integer recursionDepth;
    public static List<String> events;
    public static Map<String, List<Map<String, String>>> observations;

    public static void capture() {
        if (!enabled) return;
        String ev = String.valueOf(Trigger.operationType);
        events.add(ev);
        if (!observations.containsKey(ev)) observations.put(ev, new List<Map<String, String>>());
        Map<String, String> o = new Map<String, String>();
        o.put('flags', String.valueOf(Trigger.isExecuting)+'|'+Trigger.isBefore+'|'+Trigger.isAfter+'|'+Trigger.isInsert+'|'+Trigger.isUpdate+'|'+Trigger.isDelete+'|'+Trigger.isUndelete);
        o.put('operation', ev);
        o.put('size', String.valueOf(Trigger.size));
        o.put('nulls', String.valueOf(Trigger.new==null)+'|'+(Trigger.old==null)+'|'+(Trigger.newMap==null)+'|'+(Trigger.oldMap==null));
        o.put('sizes', (Trigger.new==null?'null':String.valueOf(Trigger.new.size()))+'|'+(Trigger.old==null?'null':String.valueOf(Trigger.old.size()))+'|'+(Trigger.newMap==null?'null':String.valueOf(Trigger.newMap.size()))+'|'+(Trigger.oldMap==null?'null':String.valueOf(Trigger.oldMap.size())));
        A37Probe__c fresh = Trigger.new==null || Trigger.new.isEmpty() ? null : (A37Probe__c)Trigger.new[0];
        A37Probe__c prior = Trigger.old==null || Trigger.old.isEmpty() ? null : (A37Probe__c)Trigger.old[0];
        o.put('new-score', fresh==null?'absent':String.valueOf(fresh.Score__c));
        o.put('old-score', prior==null?'absent':String.valueOf(prior.Score__c));
        o.put('new-id-null', fresh==null?'absent':String.valueOf(fresh.Id==null));
        o.put('old-id-null', prior==null?'absent':String.valueOf(prior.Id==null));
        o.put('new-map-member', fresh==null || Trigger.newMap==null?'absent':String.valueOf(Trigger.newMap.containsKey(fresh.Id)));
        o.put('old-map-member', prior==null || Trigger.oldMap==null?'absent':String.valueOf(Trigger.oldMap.containsKey(prior.Id)));
        o.put('new-map-reference', fresh==null || Trigger.newMap==null?'absent':String.valueOf(Trigger.newMap.get(fresh.Id)===fresh));
        o.put('old-map-reference', prior==null || Trigger.oldMap==null?'absent':String.valueOf(Trigger.oldMap.get(prior.Id)===prior));
        o.put('converted', fresh==null?'absent':String.valueOf(((A37Probe__c)(SObject)fresh).Score__c));
        o.put('delta', fresh==null || prior==null?'absent':(fresh.Score__c==null || prior.Score__c==null?'null':String.valueOf(fresh.Score__c-prior.Score__c)));
        o.put('depth', String.valueOf(recursionDepth));
        o.put('mutation', 'none');
        observations.get(ev).add(o);
        if (ev==targetEvent) {
            try {
                if (action=='new-field') fresh.Score__c=9;
                else if (action=='old-field') prior.Score__c=9;
                else if (action=='new-null') fresh.Score__c=null;
                else if (action=='new-list-add') Trigger.new.add(new A37Probe__c(Name='Extra'));
                else if (action=='old-list-clear') Trigger.old.clear();
                else if (action=='new-map-clear') Trigger.newMap.clear();
                else if (action=='old-map-clear') Trigger.oldMap.clear();
                if (action!='none') o.put('mutation','ok');
            } catch (Exception e) { o.put('mutation',e.getTypeName()); }
            if (action=='error-all' || action=='error-first' || action=='error-position-first' || action=='field-error') {
                List<SObject> affected=Trigger.isDelete?Trigger.old:Trigger.new;
                for(Integer i=0;i<affected.size();i++) {
                    if (action=='error-all' || (action=='error-position-first' && i==0) || ((action=='error-first' || action=='field-error') && affected[i].get('Name')=='A37-0')) {
                        if(action=='field-error') ((A37Probe__c)affected[i]).Score__c.addError('A37 field rejected');
                        else affected[i].addError('A37 record rejected');
                    }
                }
            }
            if (action=='throw') throw new A37Exception('A37 fixture throw');
        }
        if (action=='recurse' && Trigger.isAfter && (Trigger.isInsert || Trigger.isUpdate) && recursionDepth<recursionLimit) {
            recursionDepth++;
            List<A37Probe__c> changes=new List<A37Probe__c>();
            for(SObject s:Trigger.new) changes.add(new A37Probe__c(Id=s.Id,Score__c=recursionDepth));
            update changes;
            recursionDepth--;
        }
    }
    public class A37Exception extends Exception {}

    public static String run(String ev,Integer n,String mode,String metric) {
        Savepoint sp=Database.setSavepoint();
        try {
            enabled=false;
            List<A37Probe__c> rows=new List<A37Probe__c>();
            for(Integer i=0;i<n;i++) rows.add(new A37Probe__c(Name='A37-'+i,Score__c=mode=='score-null'?null:0));
            if (!ev.endsWith('INSERT')) insert rows;
            if (ev=='AFTER_UNDELETE') delete rows;
            events=new List<String>(); observations=new Map<String,List<Map<String,String>>>();
            targetEvent=ev; action=mode; recursionDepth=0;
            recursionLimit=mode=='recurse'?n:0;
            if(mode=='recurse') { rows=new List<A37Probe__c>{new A37Probe__c(Name='A37-recursion',Score__c=0)}; }
            if(ev.endsWith('UPDATE')) for(A37Probe__c row:rows) row.Score__c=mode=='score-null'?null:1;
            enabled=true;
            List<String> outcomes=new List<String>();
            try {
                Boolean atomic=metric=='atomic';
                if(ev.endsWith('INSERT')) for(Database.SaveResult s:Database.insert(rows,atomic)) outcomes.add(result(s.isSuccess(),s.getErrors()));
                else if(ev.endsWith('UPDATE')) for(Database.SaveResult s:Database.update(rows,atomic)) outcomes.add(result(s.isSuccess(),s.getErrors()));
                else if(ev.endsWith('DELETE') && ev!='AFTER_UNDELETE') for(Database.DeleteResult s:Database.delete(rows,atomic)) outcomes.add(result(s.isSuccess(),s.getErrors()));
                else for(Database.UndeleteResult s:Database.undelete(rows,atomic)) outcomes.add(result(s.isSuccess(),s.getErrors()));
            } catch(DmlException e) { outcomes.add(e.getTypeName()+'|'+e.getNumDml()+'|'+e.getDmlStatusCode(0)); }
            enabled=false;
            if(metric=='sequence') return String.join(events,',');
            if(metric=='outcome' || metric=='atomic') return String.join(outcomes,',');
            if(metric=='stored') {
                Set<Id> ids=new Set<Id>(); for(A37Probe__c row:rows) if(row.Id!=null) ids.add(row.Id);
                List<A37Probe__c> stored=[SELECT Score__c FROM A37Probe__c WHERE Id IN :ids ORDER BY Name];
                List<String> scores=new List<String>(); for(A37Probe__c s:stored) scores.add(String.valueOf(s.Score__c));
                return String.join(scores,',');
            }
            if(metric=='persist-count') {Set<Id> ids=new Set<Id>(); for(A37Probe__c row:rows) if(row.Id!=null) ids.add(row.Id); return String.valueOf([SELECT COUNT() FROM A37Probe__c WHERE Id IN :ids]);}
            if(!observations.containsKey(ev)) return 'no-event';
            List<String> values=new List<String>();
            for(Map<String,String> o:observations.get(ev)) values.add(o.get(metric));
            return String.join(values,',');
        } finally { enabled=false; Database.rollback(sp); Database.releaseSavepoint(sp); }
    }
    private static String result(Boolean success,Database.Error[] errors) {
        if(success) return 'ok';
        List<String> messages=new List<String>();
        for(Database.Error e:errors) messages.add(String.valueOf(e.getStatusCode())+'|'+e.getMessage()+'|'+String.join(e.getFields(),':'));
        return String.join(messages,';');
    }
}

